from pathlib import Path
from analyse import BASE,sha

def main():
 p=argparse.ArgumentParser();p.add_argument('--case',required=True);p.add_argument('--holding',required=True);p.add_argument('--balance',required=True);p.add_argument('--clearance',required=True);p.add_argument('--tag',required=True);a=p.parse_args();src=BASE/'results'/a.case;paths=[src/'summary.json']+[BASE/'results'/n/'summary.json' for n in [a.holding,a.balance,a.clearance]];run,hold,balance,gap=[json.loads(f.read_text()) for f in paths];assert run['status']=='RUN_COMPLETED_NOT_QUALIFIED';assert balance['case']==gap['case']==a.case and gap['actual_candidate_dynamics'];assert hold['input_hashes']['summary.json']==sha(paths[0]);assert balance['input_hashes']['summary.json']==sha(paths[0]);m=run['metrics'];root=ET.parse(src/'scene.scn').getroot();obj=root.find("Node[@name='object']");forbidden=[e.tag for e in obj.iter() if any(k in e.tag for k in ['ProjectiveConstraint','CableConstraint','RestShapeSprings','Controller','Sequence'])];assert not forbidden,'Object must remain unconstrained';window=next(w for w in balance['windows'] if w['requested_window_s']==[1.6,2.]);assert window['actually_covers_end'];mean=window['mean_group_object_wrench_N_Nm'];skin_z=sum(mean['skin'+str(i)][2] for i in range(3));pairs=m['contact_pairs'];hardware_object=[r for r in pairs if any(n.startswith('/object/') for n in r['pair']) and any(n.startswith(('/guides','/drive_')) or '/railCollision/'in n for n in r['pair'])];tests=dict(original_holding=hold['status']=='PASS_EXPERIMENTAL_HOLD_ONLY' and all(hold['tests'].values()),guide_guide_rows_zero=m['nonzero_guide_guide_rows']==0,root_contact_rows_zero=m['nonzero_new_root_contact_rows']==0,object_hardware_response_rows_zero=not hardware_object,all_three_skin_contact=m['actual_skin_contact_fingers']==[0,1,2],saved_FEM_positive=min(m['minimum_saved_volume_ratios'])>0,object_impulse_balance=balance['status']=='PASS_OBJECT_DISCRETE_IMPULSE_BALANCE_ONLY',finite_saved_hardware_clearance=gap['status']=='PASS_SAVED_INTERFINGER_ENVELOPE_CLEARANCE_ONLY',normal_native=run['process']['exit_code']==0,complete_original_window=balance['holding_window_fully_run']);d=dict(status='PASS_EXPLORATORY_UNBRACED_100G_HOLDING_ONLY' if all(tests.values()) else 'FAIL_EXPLORATORY_UNBRACED_HOLDING',tests=tests,vertical_slip_mm=hold['vertical_slip_mm'],maximum_speed_mm_s=hold['max_speed_mm_s'],minimum_support_gap_mm=hold['minimum_support_gap_mm'],maximum_support_resultant_N=hold['maximum_support_reaction_N'],hold_mean_skin_vertical_N=skin_z,weight_N=balance['mass_kg']*9.81,nonzero_guide_guide_rows=m['nonzero_guide_guide_rows'],nonzero_root_contact_rows=m['nonzero_new_root_contact_rows'],holding_solver_iteration_limit_samples=window['solver_iteration_limit_samples'],numerical_convergence='EXISTING FAIL / NEW CANDIDATE NOT QUALIFIED',physical_hardware_validation='NOT QUALIFIED',finite_wire_sliding='NOT QUALIFIED',lift_release_recovery='NOT RUN ON THIS CANDIDATE',source_sha256=sha(Path(__file__)),input_hashes={str(f.relative_to(BASE)):sha(f) for f in paths},scope='Original functional thresholds plus actual full-motion no-bracing, model-pair force provenance, saved finite hardware geometry, positive saved FEM and object momentum. Zero nonzero rows is not continuous CCD or full energy validation. No physical/material/time/mesh qualification. Real terminal crimp/bearing/bond strength and wire sliding unmeasured. Old1586/1741verdicts unchanged.');out=BASE/'results'/a.tag;out.mkdir(exist_ok=False);(out/'producer.py').write_bytes(Path(__file__).read_bytes());(out/'summary.json').write_text(json.dumps(d,indent=2));print(json.dumps(d,indent=2))
